{
  "PROP-6a4369e9-inv-047": {
    "property_id": "PROP-6a4369e9-inv-047",
    "text": "Peer-reported custody_group_count must be validated against NUMBER_OF_CUSTODY_GROUPS upper bound before use in any loop or data structure sizing. handle_custody_groups must terminate in O(NUMBER_OF_CUSTODY_GROUPS) iterations regardless of the peer-advertised value.",
    "type": "invariant",
    "assertion": "forall peer_cgc: handle_custody_groups(peer_cgc, ...) terminates AND iterations <= NUMBER_OF_CUSTODY_GROUPS, even when peer_cgc > NUMBER_OF_CUSTODY_GROUPS",
    "severity": "MEDIUM",
    "covers": "SG-006",
    "reachability": {
      "classification": "external-reachable",
      "entry_points": [
        "P2P"
      ],
      "attacker_controlled": true,
      "bug_bounty_scope": "in-scope"
    },
    "exploitability": "external-attack",
    "code_scope": {
      "locations": [
        {
          "file": "beacon_chain/networking/eth2_network.nim",
          "symbol": "lookupCgcFromPeer",
          "line_range": {
            "start": 2506,
            "end": 2531
          },
          "role": "primary",
          "note": "Returns peer.metadata.custody_group_count without any upper-bound validation against NUMBER_OF_CUSTODY_GROUPS. An attacker-controlled peer can advertise an arbitrarily high value."
        },
        {
          "file": "beacon_chain/sync/request_manager.nim",
          "symbol": "checkPeerCustody",
          "line_range": {
            "start": 313,
            "end": 372
          },
          "role": "related",
          "note": "Consumer of lookupCgcFromPeer: passes unvalidated remoteCustodyGroupCount to resolve_columns_from_custody_groups (line 345-348). An inflated value could cause excessive column resolution."
        },
        {
          "file": "beacon_chain/sync/request_manager.nim",
          "symbol": "matchIntersection",
          "line_range": {
            "start": 374,
            "end": 384
          },
          "role": "related",
          "note": "Second consumer: also calls lookupCgcFromPeer and passes result to resolve_columns_from_custody_groups without clamping."
        }
      ],
      "resolution_status": "resolved",
      "resolution_method": "manual"
    }
  }
}

